import Foundation
import AppKit

let src = "/tmp/album_thumbs"
let outDir = "/tmp/album_sheets"
try? FileManager.default.createDirectory(atPath: outDir, withIntermediateDirectories: true)
let files = try! FileManager.default.contentsOfDirectory(atPath: src).filter { $0.lowercased().hasSuffix(".jpg") }.sorted()
let cols = 4
let rows = 3
let per = cols * rows
let cellW: CGFloat = 360
let cellH: CGFloat = 280
let labelH: CGFloat = 22
let pad: CGFloat = 12

var sheet = 0
var i = 0
while i < files.count {
    let batch = Array(files[i..<min(i+per, files.count)])
    sheet += 1
    let w = pad + CGFloat(cols) * (cellW + pad)
    let h = pad + CGFloat(rows) * (cellH + labelH + pad)
    let img = NSImage(size: NSSize(width: w, height: h))
    img.lockFocus()
    NSColor(white: 0.96, alpha: 1).setFill()
    NSRect(x: 0, y: 0, width: w, height: h).fill()
    for (idx, name) in batch.enumerated() {
        let c = idx % cols
        let r = idx / cols
        let x = pad + CGFloat(c) * (cellW + pad)
        let yTop = pad + CGFloat(r) * (cellH + labelH + pad)
        // AppKit y is bottom-up; draw from top
        let y = h - yTop - cellH - labelH
        let path = src + "/" + name
        if let photo = NSImage(contentsOfFile: path) {
            let pw = photo.size.width
            let ph = photo.size.height
            let scale = min(cellW / pw, cellH / ph)
            let dw = pw * scale
            let dh = ph * scale
            let dx = x + (cellW - dw) / 2
            let dy = y + labelH + (cellH - dh) / 2
            photo.draw(in: NSRect(x: dx, y: dy, width: dw, height: dh))
        }
        let attr: [NSAttributedString.Key: Any] = [
            .font: NSFont.monospacedSystemFont(ofSize: 13, weight: .medium),
            .foregroundColor: NSColor.black
        ]
        (name as NSString).draw(at: NSPoint(x: x, y: y + 2), withAttributes: attr)
    }
    img.unlockFocus()
    let tiff = img.tiffRepresentation!
    let rep = NSBitmapImageRep(data: tiff)!
    let png = rep.representation(using: .png, properties: [:])!
    let out = "\(outDir)/sheet\(String(format: "%02d", sheet)).png"
    try! png.write(to: URL(fileURLWithPath: out))
    print(out, batch.count)
    i += per
}
