    try! data.write(to: URL(fileURLWithPath: path))
}

enum Fit { case cover, contain, squareCenter }

func drawPhoto(_ id: String, in rect: NSRect, fit: Fit) {
    guard let img = load(id) else { fputs("MISS \(id)\n", stderr); return }
    let pw = img.size.width, ph = img.size.height
    NSGraphicsContext.current?.cgContext.saveGState()
    NSBezierPath(rect: rect).addClip()
    switch fit {
    case .cover:
        let s = max(rect.width / pw, rect.height / ph)
        let dw = pw * s, dh = ph * s
        img.draw(in: NSRect(x: rect.midX - dw/2, y: rect.midY - dh/2, width: dw, height: dh))
    case .contain:
        let s = min(rect.width / pw, rect.height / ph)
        let dw = pw * s, dh = ph * s
        img.draw(in: NSRect(x: rect.midX - dw/2, y: rect.midY - dh/2, width: dw, height: dh))
    case .squareCenter:
        let side = min(pw, ph)
        let sx = (pw - side) / 2, sy = (ph - side) / 2
        // draw cropped square into rect
        let srcRect = NSRect(x: sx, y: sy, width: side, height: side)
        // NSImage draw from source: use CG
        if let cg = img.cgImage(forProposedRect: nil, context: nil, hints: nil) {
            let full = CGRect(x: 0, y: 0, width: cg.width, height: cg.height)
            // convert NSImage coords (bottom-left) to CG (top-left for cropping)
            let cropY = CGFloat(cg.height) - sy - side
            if let cropped = cg.cropping(to: CGRect(x: sx * CGFloat(cg.width)/pw,
                                                    y: cropY * CGFloat(cg.height)/ph,
                                                    width: side * CGFloat(cg.width)/pw,
                                                    height: side * CGFloat(cg.height)/ph)) {
                let nsimg = NSImage(cgImage: cropped, size: NSSize(width: side, height: side))
                nsimg.draw(in: rect)
            } else {
                img.draw(in: rect)
            }
        } else {
            img.draw(in: rect)
        }
    }
    NSGraphicsContext.current?.cgContext.restoreGState()
}

