func render12(_ s: L12) -> NSImage {
    let img = NSImage(size: NSSize(width: S12, height: P12))
    img.lockFocus()
    NSColor.white.setFill()
    NSRect(x: 0, y: 0, width: S12, height: P12).fill()
    // gutter hint
    NSColor(white: 0.88, alpha: 1).setFill()
    NSRect(x: P12 - 1, y: 0, width: 2, height: P12).fill()

    let margin: CGFloat = 90
    let sq: CGFloat = P12 - margin * 2 // ~1020

    func centerSq(page: Int, id: String) {
        let ox = page == 0 ? CGFloat(0) : P12
        let r = NSRect(x: ox + margin, y: margin, width: sq, height: sq)
        drawPhoto(id, in: r, fit: .squareCenter)
        label(id, at: NSPoint(x: r.minX + 10, y: r.minY + 10), size: 14)
    }

    func textPage(page: Int, text: String) {
        let ox = page == 0 ? CGFloat(0) : P12
        let para = text as NSString
        let font = NSFont.systemFont(ofSize: 36, weight: .light)
        let attr: [NSAttributedString.Key: Any] = [
            .font: font,
            .foregroundColor: NSColor(white: 0.2, alpha: 1),
            .paragraphStyle: {
                let p = NSMutableParagraphStyle()
                p.alignment = .center
                p.lineSpacing = 10
                return p
            }()
        ]
        let box = NSRect(x: ox + 120, y: P12/2 - 80, width: P12 - 240, height: 160)
        para.draw(in: box, withAttributes: attr)
    }

    switch s.kind {
    case .centerSquare(let a):
        centerSq(page: 0, id: a)
    case .centerSquareText(let a, let t):
        centerSq(page: 0, id: a)
        textPage(page: 1, text: t)
    case .twoCenter(let a, let b):
        centerSq(page: 0, id: a)
        centerSq(page: 1, id: b)
    case .grid2x2(let arr):
        // 2x2 on whole spread = one 2x2 per? Spec: 四宫格 on square album - put 2x2 on LEFT page only, or 4 across spread as 2 per page
        // 每页 2x2 would be 8 photos. Better: spread has 4 equal squares - 2 left 2 right (each page 1 col x 2) OR each page 2x2 with 4 photos total means 2 per page in a column... 
        // Classic: left page 2x2 grid of 4? that's 4 on one page. For 4 photos: 2 left stacked, 2 right stacked OR 2x2 on left and blank right.
        // Use: each page has 2 squares stacked (四宫 across spread)
        let g: CGFloat = 24
        let cell = (P12 - margin * 2 - g) / 2
        let ids = arr
        for i in 0..<min(4, ids.count) {
            let page = i < 2 ? 0 : 1
            let local = i % 2
            let ox = page == 0 ? CGFloat(0) : P12
            // 2 per page side by side for square feel, or 2x2:
            // page layout 2x2: row = local/2 col = local%2 with 2 items -> use 1x2 vertical stack for consistency with "统一"
            // Actually 2x2 on spread: 
            let col = i % 2
            let row = i / 2
            // reinterpret: left page 2x1 (two stacked), right page 2x1
            let pageI = i < 2 ? 0 : 1
            let idx = i % 2
            let ox2 = pageI == 0 ? CGFloat(0) : P12
            let side = P12 - margin * 2
            let cellH = (side - g) / 2
            // make them square: width = cellH, centered horizontally
            let cellW = cellH
            let x = ox2 + (P12 - cellW) / 2
            let y = margin + CGFloat(1 - idx) * (cellH + g)
            let r = NSRect(x: x, y: y, width: cellW, height: cellH)
            drawPhoto(ids[i], in: r, fit: .squareCenter)
            label(ids[i], at: NSPoint(x: r.minX + 8, y: r.minY + 8), size: 12)
        }
        _ = col; _ = row; _ = cell
    case .grid3(let a, let b, let c):
        let ids = [a,b,c]
        let g: CGFloat = 20
        let cell = (S12 - margin * 2 - g * 2) / 3
        for (i, id) in ids.enumerated() {
            let x = margin + CGFloat(i) * (cell + g)
            let y = (P12 - cell) / 2
            let r = NSRect(x: x, y: y, width: cell, height: cell)
            drawPhoto(id, in: r, fit: .squareCenter)
            label(id, at: NSPoint(x: r.minX + 8, y: r.minY + 8), size: 12)
        }
    case .diptych(let a, let b):
        centerSq(page: 0, id: a); centerSq(page: 1, id: b)
    }

    let title = String(format: "%02d  %@", s.no, s.scene) as NSString
    let ta: [NSAttributedString.Key: Any] = [
        .font: NSFont.systemFont(ofSize: 22, weight: .regular),
        .foregroundColor: NSColor(white: 0.25, alpha: 1)
    ]
    title.draw(at: NSPoint(x: 24, y: P12 - 36), withAttributes: ta)
    img.unlockFocus()
    return img
}

