enum Fit { case cover, squareCenter }

func drawPhoto(_ id: String, in rect: NSRect, fit: Fit) {
    guard let img = load(id) else { fputs("MISS \(id)\n", stderr); return }
    let pw = img.size.width, ph = img.size.height
    NSGraphicsContext.current?.cgContext.saveGState()
    NSBezierPath(rect: rect).addClip()
    switch fit {
    case .cover:
        let s = max(rect.width / pw, rect.height / ph)
        let dw = pw * s, dh = ph * s
        img.draw(in: NSRect(x: rect.midX - dw/2, y: rect.midY - dh/2, width: dw, height: dh))
    case .squareCenter:
        let side = min(pw, ph)
        let sx = (pw - side) / 2
        let sy = (ph - side) / 2
        if let cg = img.cgImage(forProposedRect: nil, context: nil, hints: nil) {
            let scaleX = CGFloat(cg.width) / pw
            let scaleY = CGFloat(cg.height) / ph
            let cropY = CGFloat(cg.height) - (sy + side) * scaleY
            if let cropped = cg.cropping(to: CGRect(x: sx * scaleX, y: cropY,
                                                    width: side * scaleX, height: side * scaleY)) {
                NSImage(cgImage: cropped, size: NSSize(width: side, height: side)).draw(in: rect)
            } else {
                img.draw(in: rect)
            }
        } else {
            img.draw(in: rect)
        }
    }
    NSGraphicsContext.current?.cgContext.restoreGState()
}

func label(_ text: String, at p: NSPoint, size: CGFloat = 16, white: Bool = true) {
    let attr: [NSAttributedString.Key: Any] = [
        .font: NSFont.monospacedSystemFont(ofSize: size, weight: .semibold),
        .foregroundColor: white ? NSColor.white : NSColor.black,
        .backgroundColor: white ? NSColor(white: 0, alpha: 0.4) : NSColor.clear
    ]
    (text as NSString).draw(at: p, withAttributes: attr)
}

