// Face / subject center in normalized image coords (0-1), origin top-left for Vision
func subjectCenter(cg: CGImage) -> (CGFloat, CGFloat) {
    let req = VNDetectFaceRectanglesRequest()
    let handler = VNImageRequestHandler(cgImage: cg, options: [:])
    try? handler.perform([req])
    let faces = (req.results as? [VNFaceObservation]) ?? []
    if !faces.isEmpty {
        var sx: CGFloat = 0, sy: CGFloat = 0, wsum: CGFloat = 0
        for f in faces {
            let a = f.boundingBox.width * f.boundingBox.height
            // Vision: origin bottom-left
            let cx = f.boundingBox.midX
            let cy = 1 - f.boundingBox.midY // convert to top-left-ish for mental model; we'll use bottom-left consistently
            sx += cx * a
            sy += f.boundingBox.midY * a // keep Vision bottom-left Y
            wsum += a
        }
        return (sx / wsum, sy / wsum) // x 0-1 left-right, y 0-1 bottom-top (Vision)
    }
    // fallback: slightly lower-center (couples often stand in lower half of landscapes)
    return (0.5, 0.42)
}

/// Cover-fit rect into destination, anchoring on subject so faces stay in frame
func drawCover(_ id: String, in dest: NSRect, biasX: CGFloat? = nil) {
    guard let (cg, pw, ph) = loadCG(id) else { fputs("miss \(id)\n", stderr); return }
    let (sx, sy) = subjectCenter(cg: cg)
    let scale = max(dest.width / pw, dest.height / ph)
    let dw = pw * scale, dh = ph * scale
    // Desired: subject maps near dest center (or biasX)
    let targetX = biasX ?? dest.midX
    let targetY = dest.midY
    // subject pixel in image (Vision y from bottom)
    let subjPX = sx * pw
    let subjPY = sy * ph // from bottom in image space matching NS draw
    var originX = targetX - subjPX * scale
    var originY = targetY - subjPY * scale
    // clamp so we still cover dest
    let minX = dest.maxX - dw, maxX = dest.minX
    let minY = dest.maxY - dh, maxY = dest.minY
    originX = min(max(originX, minX), maxX)
    originY = min(max(originY, minY), maxY)

    NSGraphicsContext.current?.cgContext.saveGState()
    NSBezierPath(rect: dest).addClip()
    let nsimg = NSImage(cgImage: cg, size: NSSize(width: pw, height: ph))
    nsimg.draw(in: NSRect(x: originX, y: originY, width: dw, height: dh),
               from: .zero, operation: .copy, fraction: 1)
    NSGraphicsContext.current?.cgContext.restoreGState()
}

/// Square crop around subject
func drawSquareSmart(_ id: String, in dest: NSRect) {
    guard let (cg, pw, ph) = loadCG(id) else { return }
    let (sx, sy) = subjectCenter(cg: cg)
    let side = min(pw, ph)
    var x0 = sx * pw - side / 2
    var y0 = sy * ph - side / 2 // bottom-left origin
    x0 = min(max(0, x0), pw - side)
    y0 = min(max(0, y0), ph - side)
    // CG crop uses top-left origin
    let crop = CGRect(x: x0, y: ph - y0 - side, width: side, height: side)
    guard let cropped = cg.cropping(to: crop) else {
        drawCover(id, in: dest); return
    }
    NSGraphicsContext.current?.cgContext.saveGState()
    NSBezierPath(rect: dest).addClip()
    NSImage(cgImage: cropped, size: NSSize(width: side, height: side)).draw(in: dest)
    NSGraphicsContext.current?.cgContext.restoreGState()
}

