func render18(_ s: S18) -> NSImage {
    let img = NSImage(size: NSSize(width: SW, height: PH))
    img.lockFocus()
    NSColor.white.setFill()
    NSRect(x: 0, y: 0, width: SW, height: PH).fill()
    let left = NSRect(x: 0, y: 0, width: PW, height: PH)
    let right = NSRect(x: PW, y: 0, width: PW, height: PH)
    let m: CGFloat = 36
    let g: CGFloat = 16

    switch s.kind {
    case .cross(let a):
        // bias subject to 38% or 62% of spread so faces avoid gutter
        guard let (cg, _, _) = loadCG(a) else { break }
        let (sx, _) = subjectCenter(cg: cg)
        // if subject naturally left, put them on left page; else right
        let bias = sx < 0.5 ? SW * 0.32 : SW * 0.68
        drawCover(a, in: NSRect(x: 0, y: 0, width: SW, height: PH), biasX: bias)
        // hairline gutter cue
        NSColor(white: 1, alpha: 0.2).setFill()
        NSRect(x: PW - 1, y: 0, width: 2, height: PH).fill()
        badge(a, at: NSPoint(x: 16, y: 14))
    case .pair(let a, let b):
        drawCover(a, in: left)
        drawCover(b, in: right)
        badge(a, at: NSPoint(x: 16, y: 14))
        badge(b, at: NSPoint(x: PW + 16, y: 14))
    case .floatPair(let a, let b):
        drawCover(a, in: left.insetBy(dx: m, dy: m))
        drawCover(b, in: right.insetBy(dx: m, dy: m))
        badge(a, at: NSPoint(x: m + 10, y: m + 10))
        badge(b, at: NSPoint(x: PW + m + 10, y: m + 10))
    case .heroSmall(let hero, let s1, let s2):
        drawCover(hero, in: left)
        let h = (PH - m * 2 - g) / 2
        drawCover(s1, in: NSRect(x: PW + m, y: PH - m - h, width: PW - 2*m, height: h))
        drawCover(s2, in: NSRect(x: PW + m, y: m, width: PW - 2*m, height: h))
        badge(hero, at: NSPoint(x: 16, y: 14))
        badge(s1, at: NSPoint(x: PW + m + 8, y: PH - m - h + 8))
        badge(s2, at: NSPoint(x: PW + m + 8, y: m + 8))
    case .smallHero(let s1, let s2, let hero):
        let h = (PH - m * 2 - g) / 2
        drawCover(s1, in: NSRect(x: m, y: PH - m - h, width: PW - 2*m, height: h))
        drawCover(s2, in: NSRect(x: m, y: m, width: PW - 2*m, height: h))
        drawCover(hero, in: right)
        badge(s1, at: NSPoint(x: m + 8, y: PH - m - h + 8))
        badge(s2, at: NSPoint(x: m + 8, y: m + 8))
        badge(hero, at: NSPoint(x: PW + 16, y: 14))
    case .triad: break
    }
    title18(String(format: "%02d  %@", s.no, s.scene), on: PH)
    img.unlockFocus()
    return img
}

