func render12(_ s: S12) -> NSImage {
    let img = NSImage(size: NSSize(width: S, height: P))
    img.lockFocus()
    NSColor.white.setFill()
    NSRect(x: 0, y: 0, width: S, height: P).fill()
    let left = NSRect(x: 0, y: 0, width: P, height: P)
    let right = NSRect(x: P, y: 0, width: P, height: P)
    let m: CGFloat = 72
    let g: CGFloat = 14

    var darkTitle = true
    switch s.kind {
    case .bleedPair(let a, let b):
        drawSquareSmart(a, in: left)
        drawSquareSmart(b, in: right)
        badge(a, at: NSPoint(x: 12, y: 12))
        badge(b, at: NSPoint(x: P + 12, y: 12))
        darkTitle = false
    case .bleedSolo(let a):
        drawSquareSmart(a, in: left)
        darkTitle = false
    case .framePair(let a, let b):
        let sq = P - m * 2
        drawSquareSmart(a, in: NSRect(x: m, y: m, width: sq, height: sq))
        drawSquareSmart(b, in: NSRect(x: P + m, y: m, width: sq, height: sq))
        badge(a, at: NSPoint(x: m + 8, y: m + 8))
        badge(b, at: NSPoint(x: P + m + 8, y: m + 8))
    case .grid4(let ids):
        let cell = (P - m * 2 - g) / 2
        for i in 0..<4 {
            let page = i < 2 ? 0 : 1
            let idx = i % 2
            let ox = CGFloat(page) * P
            // 2x2 per page would be 8; we do 2 stacked centered per page
            let x = ox + (P - cell) / 2
            let y = m + CGFloat(1 - idx) * (cell + g)
            drawSquareSmart(ids[i], in: NSRect(x: x, y: y, width: cell, height: cell))
            badge(ids[i], at: NSPoint(x: x + 6, y: y + 6))
        }
    case .heroBleedTwo(let hero, let s1, let s2):
        drawSquareSmart(hero, in: left)
        let cell = (P - m * 2 - g) / 2
        let x = P + (P - cell) / 2
        drawSquareSmart(s1, in: NSRect(x: x, y: m + cell + g, width: cell, height: cell))
        drawSquareSmart(s2, in: NSRect(x: x, y: m, width: cell, height: cell))
        badge(hero, at: NSPoint(x: 12, y: 12))
        badge(s1, at: NSPoint(x: x + 6, y: m + cell + g + 6))
        badge(s2, at: NSPoint(x: x + 6, y: m + 6))
        darkTitle = false
    case .asymmetric: break
    }
    title12(String(format: "%02d  %@", s.no, s.scene), on: P, dark: darkTitle)
    img.unlockFocus()
    return img
}

