func render12(_ s: S12) -> NSImage {
    let img = NSImage(size: NSSize(width: S, height: P))
    img.lockFocus()
    NSColor.black.setFill()
    NSRect(x: 0, y: 0, width: S, height: P).fill()
    switch s.kind {
    case .twin(let a, let b):
        drawSquarePage(a, in: NSRect(x: 0, y: 0, width: P, height: P))
        drawSquarePage(b, in: NSRect(x: P, y: 0, width: P, height: P))
        badge(a, NSPoint(x: 8, y: 8)); badge(b, NSPoint(x: P + 8, y: 8))
    case .fourV(let a, let b, let c, let d):
        let half = P / 2
        drawPortraitSlot(a, in: NSRect(x: 0, y: 0, width: half, height: P))
        drawPortraitSlot(b, in: NSRect(x: half, y: 0, width: half, height: P))
        drawPortraitSlot(c, in: NSRect(x: P, y: 0, width: half, height: P))
        drawPortraitSlot(d, in: NSRect(x: P + half, y: 0, width: half, height: P))
        badge(a, NSPoint(x: 6, y: 8)); badge(b, NSPoint(x: half + 6, y: 8))
        badge(c, NSPoint(x: P + 6, y: 8)); badge(d, NSPoint(x: P + half + 6, y: 8))
    }
    cap(String(format: "%02d  %@", s.no, s.scene), h: P)
    img.unlockFocus()
    return img
}

