    top += secT
    for (i, im) in items.enumerated() {
        let col = i % 2, row = i / 2
        let x = pad + CGFloat(col) * (cw + gapC)
        let y = yTop(top + CGFloat(row) * (ch + gapC) + ch)
        im.draw(in: NSRect(x: x, y: y, width: cw, height: ch))
